import json

# Let me do a comprehensive search for any number around 13.x in page 82
data = json.load(open('/app/resources/treasury_bulletin_1982_08.json'))

for elem in data['document']['elements']:
    if isinstance(elem, dict):
        bbox = elem.get('bbox', [{}])[0] if elem.get('bbox') else {}
        page_id = bbox.get('page_id') if isinstance(bbox, dict) else None
        if page_id == 82:
            content = elem.get('content', '')
            if content:
                # Look for any numeric values in the 12-14 range that could be yields
                import re
                numbers = re.findall(r'\d+\.\d+', content)
                nums_12_14 = [n for n in numbers if 12 <= float(n) <= 14]
                if nums_12_14:
                    print(f"Found: {nums_12_14}")
                    print(f"Content sample: {content[:300]}")
                    print("---")
EOF

